// components: specs/components/*.def.ts -> the Authfly middle layer in the 9 targets of an authkit checkout.
//   authfly-codegen components [--check] --root <authkit>
// React, Solid, Vue, Svelte, Web Components and templ get one generated file per component (WC re-exported from
// components/index.ts, templ in package authfly). Twig, Latte and Jinja2 keep one macro file (macros call each other
// through _self / the same file), so the component is a generated region inside authfly/components.*, between
// `codegen:begin <name>` / `codegen:end <name>` comments; the rest of that file stays hand-written.
import { existsSync, readFileSync, readdirSync, writeFileSync } from "fs";
import { join } from "path";
import type { Component, Glyph, Heading, Layout, Message, Pill } from "./dsl-components";
import { camel, layoutBodies, layoutJs, glyphBodies, glyphJs, headingBodies, headingJs, messageBodies, messageJs, pillBodies, pillJs } from "./emit/components";

const specs = join(import.meta.dir, "../specs/components");
const pascal = (w: string) => w.split("-").map((s) => s[0].toUpperCase() + s.slice(1)).join("");
const head = (n: string) => `Code generated by authfly/codegen from specs/components/${n}.def.ts. DO NOT EDIT.`;

export async function componentSpecs(): Promise<Component[]> {
  if (!existsSync(specs)) return [];
  const out: Component[] = [];
  for (const f of readdirSync(specs).filter((f) => f.endsWith(".def.ts")).sort()) out.push((await import(join(specs, f))).default);
  return out;
}

type Out = { files: Map<string, string>; regions: Map<string, Map<string, { open: string; close: string; body: string }>> };

function surface(c: Extract<Component, { kind: "surface" }>, o: Out) {
  const P = pascal(c.name), H = head(c.name), sk = `${c.name}Skin`, t = c.tag;
  o.files.set(`react/src/components/${c.name}.tsx`, `// ${H}
// Widget surface: a <${t}> landmark (Box) with the ${c.skin} skin.
import { Box, type BoxProps } from "../ui/box/box";
import { ${sk} } from "../skin/skin";

export function ${P}({ className, tag = "${t}", ...rest }: BoxProps) {
  return <Box tag={tag} className={${sk}(className)} {...rest} />;
}
`);
  o.files.set(`solid/src/components/${c.name}.tsx`, `// ${H}
import { splitProps } from "solid-js";
import { Box, type BoxProps } from "../ui/box/box.solid";
import { ${sk} } from "../skin/skin";

/** Widget surface: a <${t}> landmark with the ${c.skin} skin. */
export function ${P}(props: BoxProps) {
  const [l, rest] = splitProps(props, ["class", "className", "tag"]);
  return <Box tag={l.tag ?? "${t}"} {...rest} class={${sk}(l.class ?? l.className)} />;
}
`);
  o.files.set(`vue/src/components/${P}.vue`, `<script setup lang="ts">
// ${H}
import Box from "../ui/box/Box.vue";
import { ${sk} } from "../skin/skin";
defineOptions({ inheritAttrs: false });
defineProps<{ class?: string }>();
</script>
<template><Box tag="${t}" v-bind="$attrs" :class="${sk}($props.class)"><slot /></Box></template>
`);
  o.files.set(`svelte/src/components/${P}.svelte`, `<script lang="ts">
  // ${H}
  import type { Snippet } from "svelte";
  import Box from "../ui/box/Box.svelte";
  import { ${sk} } from "../skin/skin";
  let { class: className, children, ...rest }: { class?: string; children?: Snippet; [k: string]: unknown } = $props();
</script>

<Box tag="${t}" {...rest} class={${sk}(className)}>{@render children?.()}</Box>
`);
  o.files.set(`webcomponent/src/components/${c.name}.ts`, `// ${H}
// Widget surface: a <${t}> landmark (the Box primitive) with the ${c.skin} skin.
import type { Children } from "../utils/wc";
import { renderBox, type BoxElementProps } from "../ui/box/box.wc";
import { ${sk} } from "../skin/skin";

export function ${c.name}(props: BoxElementProps, children: Children): Element {
  const { class: className, tag = "${t}", ...rest } = props;
  return renderBox({ tag, ...rest, class: ${sk}(className) }, children);
}
`);
  o.files.set(`templ/authfly/${c.name.replace(/-/g, "_")}.templ`, `// ${H}
// ${P}: the widget surface, a <${t}> landmark (the Box primitive) with the ${c.skin} skin.
package authfly

import "github.com/authfly/authkit/packages/ui/templ/ui/box"

templ ${P}(class string, attrs templ.Attributes) {
	@box.Box(box.BoxProps{Tag: "${t}", Class: ${P}Skin(class), Attrs: attrs}) {
		{ children... }
	}
}
`);
  const reg = region(o, c.name);
  reg("twig/authfly/components.html.twig", `{#- codegen:begin ${c.name}: ${H} -#}`, `{#- codegen:end ${c.name} -#}`,
    `{%- macro ${c.name}(class, attrs, children) -%}
{{ _self.box('${t}', af_skin('${c.skin}', class), attrs, children) }}
{%- endmacro -%}`);
  reg("latte/authfly/components.latte", `{* codegen:begin ${c.name}: ${H} *}`, `{* codegen:end ${c.name} *}`,
    `{define ${c.name}, string $class = '', array $attrs = [], $children = ''}
{include box, '${t}', afSkin('${c.skin}', $class), $attrs, $children}
{/define}`);
  reg("jinja2/authfly/components.html.j2", `{#- codegen:begin ${c.name}: ${H} -#}`, `{#- codegen:end ${c.name} -#}`,
    `{%- macro ${c.name}(cls='', attrs={}, children='') -%}{{ box('${t}', af_skin('${c.skin}', cls), attrs, children) }}{%- endmacro -%}`);
}

function region(o: Out, name: string) {
  return (rel: string, open: string, close: string, body: string) => {
    if (!o.regions.has(rel)) o.regions.set(rel, new Map());
    o.regions.get(rel)!.set(name, { open, close, body });
  };
}

/** Server macro regions (Twig, Latte, Jinja2) with the codegen:begin/end markers. */
function serverRegions(o: Out, name: string, b: { twig: string; latte: string; jinja2: string }, spec = name) {
  const H = head(spec), reg = region(o, name);
  reg("twig/authfly/components.html.twig", `{#- codegen:begin ${name}: ${H} -#}`, `{#- codegen:end ${name} -#}`, b.twig);
  reg("latte/authfly/components.latte", `{* codegen:begin ${name}: ${H} *}`, `{* codegen:end ${name} *}`, b.latte);
  reg("jinja2/authfly/components.html.j2", `{#- codegen:begin ${name}: ${H} -#}`, `{#- codegen:end ${name} -#}`, b.jinja2);
}

/** Header line in a JS-family file: first line (tsx), first line of the script block (vue, svelte). */
const hdr = (kind: "tsx" | "vue" | "svelte", H: string, body: string) =>
  kind === "tsx" ? `// ${H}\n${body}`
  : kind === "vue" ? body.replace(`<script setup lang="ts">\n`, `<script setup lang="ts">\n// ${H}\n`)
  : body.replace(`<script lang="ts">\n`, `<script lang="ts">\n  // ${H}\n`);

function messageKind(c: Message, o: Out) {
  const P = pascal(c.name), H = head(c.name), j = messageJs(c), b = messageBodies(c), sk = `${camel(c.skin)}Skin`;
  o.files.set(`react/src/components/${c.name}.tsx`, hdr("tsx", H, j.react));
  o.files.set(`solid/src/components/${c.name}.tsx`, hdr("tsx", H, j.solid));
  o.files.set(`vue/src/components/${P}.vue`, hdr("vue", H, j.vue));
  o.files.set(`svelte/src/components/${P}.svelte`, hdr("svelte", H, j.svelte));
  o.files.set(`webcomponent/src/components/${c.name}.ts`, `// ${H}
import type { Children } from "../utils/wc";
import { renderBox } from "../ui/box/box.wc";
import { ${sk}, type Tone } from "../skin/skin";
import { lucideIcon } from "./lucide-icon";

${b.wc}`);
  o.files.set(`templ/authfly/${c.name.replace(/-/g, "_")}.templ`, `// ${H}
package authfly

import "github.com/authfly/authkit/packages/ui/templ/ui/box"

${b.templ}`);
  serverRegions(o, c.name, b);
}

function pillKind(c: Pill, o: Out) {
  const P = pascal(c.name), T = pascal(c.tile.name), H = head(c.name), j = pillJs(c), b = pillBodies(c);
  const sk = `${camel(c.skin)}Skin`, tsk = `${camel(c.tile.skin)}Skin`;
  o.files.set(`react/src/components/${c.name}.tsx`, hdr("tsx", H, j.react));
  o.files.set(`solid/src/components/${c.name}.tsx`, hdr("tsx", H, j.solid));
  o.files.set(`vue/src/components/${P}.vue`, hdr("vue", H, j.vue));
  o.files.set(`vue/src/components/${T}.vue`, hdr("vue", H, j.vueTile));
  o.files.set(`svelte/src/components/${P}.svelte`, hdr("svelte", H, j.svelte));
  o.files.set(`svelte/src/components/${T}.svelte`, hdr("svelte", H, j.svelteTile));
  o.files.set(`webcomponent/src/components/${c.name}.ts`, `// ${H}
import type { Children } from "../utils/wc";
import { renderText, type TextElementProps } from "../ui/text/text.wc";
import { ${sk}, ${tsk}, type BadgeVariant } from "../skin/skin";
import { lucideIcon } from "./lucide-icon";

${b.wc}`);
  o.files.set(`templ/authfly/${c.name.replace(/-/g, "_")}.templ`, `// ${H}
package authfly

import "github.com/authfly/authkit/packages/ui/templ/ui/text"

${b.templ}`);
  serverRegions(o, c.name, b);
}

/** The four JS-family whole files of a kind with one component file per runtime. */
function jsFiles(o: Out, c: Component, H: string, j: { react: string; solid: string; vue: string; svelte: string }) {
  const P = pascal(c.name);
  o.files.set(`react/src/components/${c.name}.tsx`, hdr("tsx", H, j.react));
  o.files.set(`solid/src/components/${c.name}.tsx`, hdr("tsx", H, j.solid));
  o.files.set(`vue/src/components/${P}.vue`, hdr("vue", H, j.vue));
  o.files.set(`svelte/src/components/${P}.svelte`, hdr("svelte", H, j.svelte));
}

function headingKind(c: Heading, o: Out) {
  const H = head(c.name), b = headingBodies(c);
  jsFiles(o, c, H, headingJs(c));
  o.files.set(`webcomponent/src/components/${c.name}.ts`, `// ${H}
import type { Children } from "../utils/wc";
import { renderText, type TextElementProps } from "../ui/text/text.wc";
import { cn } from "../utils";
import { textSkin } from "../skin/skin";

${b.wc}`);
  o.files.set(`templ/authfly/${c.name.replace(/-/g, "_")}.templ`, `// ${H}
package authfly

import "github.com/authfly/authkit/packages/ui/templ/ui/text"

${b.templ}`);
  serverRegions(o, c.name, b);
}

function glyphKind(c: Glyph, o: Out) {
  const H = head(c.name), b = glyphBodies(c);
  jsFiles(o, c, H, glyphJs(c));
  o.files.set(`webcomponent/src/components/${c.name}.ts`, `// ${H}
import { renderIcon } from "../ui/icon/icon.wc";
import type { IconSize } from "../ui/icon/icon.shared";
import { LUCIDE } from "./lucide-icons";

${b.wc}`);
  o.files.set(`templ/authfly/${c.name.replace(/-/g, "_")}.templ`, `// ${H}
package authfly

import "github.com/authfly/authkit/packages/ui/templ/ui/icon"

${b.templ}`);
  serverRegions(o, c.name, b);
}

function layoutKind(c: Layout, o: Out) {
  const H = head(c.name), b = layoutBodies();
  for (const [rel, body] of Object.entries(layoutJs()))
    o.files.set(rel, rel.endsWith(".vue") ? hdr("vue", H, body) : rel.endsWith(".svelte") ? hdr("svelte", H, body) : hdr("tsx", H, body));
  o.files.set(`webcomponent/src/components/${c.name}.ts`, `// ${H}
// Stack / Group over Box (8px-step gaps) and Form over the Form primitive (Authfly grid).
import type { Children } from "../utils/wc";
import { renderBox, type BoxElementProps } from "../ui/box/box.wc";
import { renderForm } from "../ui/form/form.wc";
import { cn } from "../utils";

${b.wc}`);
  o.files.set(`templ/authfly/${c.name}.templ`, `// ${H}
package authfly

import (
\t"github.com/authfly/authkit/packages/ui/templ/ui/box"
\t"github.com/authfly/authkit/packages/ui/templ/ui/form"
)

${b.templ}`);
  serverRegions(o, c.name, { twig: b.twig.layout, latte: b.latte.layout, jinja2: b.jinja2.layout });
  serverRegions(o, `${c.name}-prim`, { twig: b.twig.prim, latte: b.latte.prim, jinja2: b.jinja2.prim }, c.name);
}

/** packages/ui-relative path -> content (whole files) and region bodies. */
export async function componentOutputs(): Promise<Out> {
  const o: Out = { files: new Map(), regions: new Map() };
  for (const c of await componentSpecs()) {
    if (c.kind === "surface") surface(c, o);
    else if (c.kind === "message") messageKind(c, o);
    else if (c.kind === "pill") pillKind(c, o);
    else if (c.kind === "heading") headingKind(c, o);
    else if (c.kind === "glyph") glyphKind(c, o);
    else layoutKind(c, o);
  }
  return o;
}

const esc = (s: string) => s.replace(/[.*+?^${}()|[\]\\]/g, "\\$&");

export async function components(root: string, check: boolean): Promise<number> {
  const o = await componentOutputs();
  let bad = 0, n = 0;
  const put = (rel: string, cur: string | null, body: string, what: string) => {
    n++;
    if (cur === body) return;
    if (check) { console.error(`components: packages/ui/${rel} ${what}`); bad++; }
    else { writeFileSync(join(root, "packages/ui", rel), body); console.log(`components: wrote packages/ui/${rel}`); }
  };
  for (const [rel, body] of o.files) {
    const p = join(root, "packages/ui", rel);
    put(rel, existsSync(p) ? readFileSync(p, "utf8") : null, body, existsSync(p) ? "differs from the spec" : "missing");
  }
  for (const [rel, regs] of o.regions) {
    const p = join(root, "packages/ui", rel);
    let txt = readFileSync(p, "utf8");
    const cur = txt;
    for (const [name, r] of regs) {
      const re = new RegExp(`${esc(r.open)}\\n[\\s\\S]*?\\n${esc(r.close)}`);
      const block = `${r.open}\n${r.body}\n${r.close}`;
      if (!re.test(txt)) { if (check) { console.error(`components: packages/ui/${rel} has no codegen region ${name}`); bad++; continue; }
        throw new Error(`components: packages/ui/${rel}: add the ${name} region markers (${r.open} / ${r.close})`); }
      txt = txt.replace(re, () => block);
    }
    put(rel, cur, txt, "region differs from the spec");
  }
  if (check && !bad) console.log(`components: ${n} generated files/regions up to date`);
  return bad;
}
